import java.util.*;
import java.io.*;

public class tr0 {
	static PrintWriter out;
	static StringBuilder sb;
	static int mod = 998244353;
	static long inf = (long) 1e18 + 1;
	static int[] col;
	static int n, m;
	static ArrayList<Integer>[] ad;
	static long[][][] memo;
	static HashSet<Integer> h;
	static int[] a;
	static Integer[][] g;

	public static void main(String[] args) throws Exception {
		Scanner sc = new Scanner(System.in);
		out = new PrintWriter(System.out);
		int n = sc.nextInt();
		long k = sc.nextLong();
		if (k >= n) {
			System.out.println(0);
			return;
		}
		long[] fac = new long[n + 1];
		fac[0] = 1;
		for (int i = 0; i < n; i++)
			fac[i + 1] = (i + 1) * fac[i] % mod;
		if (k == 0) {
			System.out.println(fac[n]);
			return;
		}
		int k1 = (int) k;
		int c = n - k1;
		long ans = fac[n] * modPow(fac[c], mod - 2) % mod;
		ans = ans*modPow(fac[n - c], mod - 2)%mod;

		long tem = 0;
		for (int i = 0; i <= c; i++)
			if (i % 2 == 0) {
				long tem1 = fac[c] * modPow(fac[i], mod - 2) % mod;
				tem1 = tem1 * modPow(fac[c - i], mod - 2) % mod;
				tem1 = tem1 * modPow(c - i, n) % mod;
				tem = (tem1 + tem) % mod;
			} else {
				long tem1 = fac[c] * modPow(fac[i], mod - 2) % mod;
				tem1 = tem1 * modPow(fac[c - i], mod - 2) % mod;
				tem1 = tem1 * modPow(c - i, n) % mod;
				tem = (-tem1 + tem + mod) % mod;
			}
		ans = ans * tem * 2 % mod;
		System.out.println(ans);
		out.flush();
	}

	static long modPow(long a, long e)

	{
		long res = 1;
		while (e > 0) {
			if ((e & 1) == 1)
				res = (res * a) % mod;
			a = (a * a) % mod;
			e >>= 1;
		}
		return res;
	}

	static class Scanner {
		StringTokenizer st;
		BufferedReader br;

		public Scanner(InputStream system) {
